DROP VIEW IF EXISTS replset.vw_month_cos_common CASCADE;  CREATE OR REPLACE VIEW replset.vw_month_cos_common AS  SELECT date_trunc('month'::text, date_period) AS repmonth,     orgs_code,     orgs_name,     shop_code,     shop_name,     sum(amount) AS amount,     sum(amountman) AS amountman,     sum(amountvatin) AS amountvatin,     sum(amountregl) AS amountregl    FROM mvw_cos_common   GROUP BY (date_trunc('month'::text, date_period)), orgs_code, orgs_name, shop_code, shop_name;
